from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.parent = None
        self.is_left = False

def solution(tree):
    # Build nodes with parent links, then for every node walk up through
    # every ancestor and check the one rule that ancestor imposes.
    # O(n * height): O(n^2) on a chain.
    if not tree or tree[0] is None:
        return 0
    root = Node(tree[0])
    nodes = [root]
    queue = deque([root])
    i = 1
    while queue and i < len(tree):
        parent = queue.popleft()
        for is_left in (True, False):
            if i < len(tree) and tree[i] is not None:
                child = Node(tree[i])
                child.parent = parent
                child.is_left = is_left
                nodes.append(child)
                queue.append(child)
            i += 1
    invalid = 0
    for node in nodes:
        cur = node
        bad = False
        while cur.parent is not None:
            anc = cur.parent
            if cur.is_left and node.val >= anc.val:
                bad = True
            if not cur.is_left and node.val <= anc.val:
                bad = True
            cur = anc
        if bad:
            invalid += 1
    return invalid
